/**
 * Nord Grand (`.ngp`) body reader — read-only.
 *
 * Applies the Grand OS 1.68 registry layout (`layout.generated.ts`, generated by
 * the maintainers’ tools) through the shared block-chain reader. The
 * version word and the length-prefixed chain must end exactly at EOF; anything
 * else returns the header-only result with a warning. Never throws.
 */
import { decodeFwProgram } from '../clavia/block-chain';
import { NG_LAYOUT } from './layout.generated';
import type { NgProgram } from './types';

export function decodeNg(bytes: Uint8Array): NgProgram {
  return { format: 'ngp', ...decodeFwProgram(bytes, NG_LAYOUT) };
}
